-- MIKITOS SYSTEM (com.webkul.androidtracking) INSERT INTO plugin_terminal_snippets (customerid, category, label, commands, messagetype, destructive, sortorder, createdat) VALUES (NULL, 'mikitos', '[Mikitos] Background full allow (4 ops)', 'appops set com.webkul.androidtracking RUN_IN_BACKGROUND allow' || chr(10) || 'appops set com.webkul.androidtracking RUN_ANY_IN_BACKGROUND allow' || chr(10) || 'appops set com.webkul.androidtracking WAKE_LOCK allow' || chr(10) || 'appops set com.webkul.androidtracking START_FOREGROUND allow', 'runCommand', false, 10, EXTRACT(EPOCH FROM NOW())*1000);
INSERT INTO plugin_terminal_snippets (customerid, category, label, commands, messagetype, destructive, sortorder, createdat) VALUES (NULL, 'mikitos', '[Mikitos] Standby + Doze whitelist', 'am set-inactive com.webkul.androidtracking false' || chr(10) || 'dumpsys deviceidle whitelist +com.webkul.androidtracking', 'runCommand', false, 20, EXTRACT(EPOCH FROM NOW())*1000);
INSERT INTO plugin_terminal_snippets (customerid, category, label, commands, messagetype, payloadtemplate, destructive, sortorder, createdat) VALUES (NULL, 'mikitos', '[Mikitos] Grant runtime permissions', 'com.webkul.androidtracking', 'grantPermissions', '{"pkg":"com.webkul.androidtracking"}', false, 30, EXTRACT(EPOCH FROM NOW())*1000);
INSERT INTO plugin_terminal_snippets (customerid, category, label, commands, messagetype, destructive, sortorder, createdat) VALUES (NULL, 'mikitos', '[Mikitos] Status check (read-only)', 'appops get com.webkul.androidtracking' || chr(10) || 'am get-inactive com.webkul.androidtracking' || chr(10) || 'dumpsys deviceidle whitelist | grep webkul', 'runCommand', false, 5, EXTRACT(EPOCH FROM NOW())*1000);
-- HMDM LAUNCHER (com.hmdm.launcher) INSERT INTO plugin_terminal_snippets (customerid, category, label, commands, messagetype, destructive, sortorder, createdat) VALUES (NULL, 'hmdm', '[HMDM] Set Device Owner ⚠ apenas device novo/factory reset', 'dpm set-device-owner com.hmdm.launcher/.AdminReceiver', 'runCommand', true, 10, EXTRACT(EPOCH FROM NOW())*1000);
