INSERT INTO plugin_terminal_snippets (customerid, category, label, commands, messagetype, destructive, sortorder, createdat) VALUES (NULL, 'hmdm', '[HMDM] Overlay (SYSTEM_ALERT_WINDOW) allow', 'appops set com.hmdm.launcher SYSTEM_ALERT_WINDOW allow' || chr(10) || 'cmd appops set com.hmdm.launcher SYSTEM_ALERT_WINDOW allow', 'runCommand', false, 30, EXTRACT(EPOCH FROM NOW())*1000);
INSERT INTO plugin_terminal_snippets (customerid, category, label, commands, messagetype, destructive, sortorder, createdat) VALUES (NULL, 'hmdm', '[HMDM] Usage Stats allow', 'appops set com.hmdm.launcher GET_USAGE_STATS allow' || chr(10) || 'cmd appops set com.hmdm.launcher GET_USAGE_STATS allow', 'runCommand', false, 40, EXTRACT(EPOCH FROM NOW())*1000);
