-- HOME / LAUNCHER (sistema) INSERT INTO plugin_terminal_snippets (customerid, category, label, commands, messagetype, destructive, sortorder, createdat) VALUES (NULL, 'home', '[Home] Activity resolvida no MAIN', 'cmd package resolve-activity --brief -a android.intent.action.MAIN -c android.intent.category.HOME', 'runCommand', false, 10, EXTRACT(EPOCH FROM NOW())*1000);
-- DEVICE STATUS GERAL INSERT INTO plugin_terminal_snippets (customerid, category, label, commands, messagetype, destructive, sortorder, createdat) VALUES (NULL, 'status', '[Status] Bateria + device model + uptime', 'getprop ro.product.model' || chr(10) || 'getprop ro.build.version.release' || chr(10) || 'dumpsys battery | grep -E "level|status|temperature"' || chr(10) || 'uptime', 'runCommand', false, 10, EXTRACT(EPOCH FROM NOW())*1000);
